    ('3a5728d6-401c-4c62-96f3-afd1239744df'::uuid, 'Incline Barbell Bench Press', 'https://qukdfjeupjhpthfbaonv.supabase.co/storage/v1/object/public/exercise-images/approved/2026-11-14/webp-768/incline-barbell-bench-press-benjamin.webp', 'https://qukdfjeupjhpthfbaonv.supabase.co/storage/v1/object/public/exercise-images/approved/2026-11-14/motion-webp/incline-barbell-bench-press-benjamin.webp', 'https://qukdfjeupjhpthfbaonv.supabase.co/storage/v1/object/public/exercise-images/anatomy/2026-11-21/incline-barbell-bench-press.webp', 'https://qukdfjeupjhpthfbaonv.supabase.co/storage/v1/object/public/exercise-images/approved/2026-11-21/motion-webp/incline-barbell-bench-press-anatomy.webp'),
    ('29685b9a-0812-4ffa-9146-0fa17fb79b7c'::uuid, 'Pec Deck Chest Fly', 'https://qukdfjeupjhpthfbaonv.supabase.co/storage/v1/object/public/exercise-images/approved/2026-11-14/webp-768/pec-deck-chest-fly-benjamin.webp', 'https://qukdfjeupjhpthfbaonv.supabase.co/storage/v1/object/public/exercise-images/approved/2026-11-14/motion-webp/pec-deck-chest-fly-benjamin.webp', 'https://qukdfjeupjhpthfbaonv.supabase.co/storage/v1/object/public/exercise-images/anatomy/2026-11-21/pec-deck-chest-fly.webp', 'https://qukdfjeupjhpthfbaonv.supabase.co/storage/v1/object/public/exercise-images/approved/2026-11-21/motion-webp/pec-deck-chest-fly-anatomy.webp'),
    ('9221786d-3249-447f-99f2-a2fd219cecee'::uuid, 'Reverse Pec Deck', 'https://qukdfjeupjhpthfbaonv.supabase.co/storage/v1/object/public/exercise-images/approved/2026-11-14/webp-768/reverse-pec-deck-benjamin.webp', 'https://qukdfjeupjhpthfbaonv.supabase.co/storage/v1/object/public/exercise-images/approved/2026-11-14/motion-webp/reverse-pec-deck-benjamin.webp', 'https://qukdfjeupjhpthfbaonv.supabase.co/storage/v1/object/public/exercise-images/anatomy/2026-11-21/reverse-pec-deck.webp', 'https://qukdfjeupjhpthfbaonv.supabase.co/storage/v1/object/public/exercise-images/approved/2026-11-21/motion-webp/reverse-pec-deck-anatomy.webp'),
    ('dc14bfdb-23e9-4a2a-9931-81741abc732e'::uuid, 'Walking Lunge', 'https://qukdfjeupjhpthfbaonv.supabase.co/storage/v1/object/public/exercise-images/approved/2026-09-29/webp-768/walking-lunge.webp', null, 'https://qukdfjeupjhpthfbaonv.supabase.co/storage/v1/object/public/exercise-images/anatomy/2026-11-21/walking-lunge.webp', null)
    ) as cards(id, name, old_image_url, old_motion_url, new_image_url, new_motion_url)
   where exercise.id = cards.id
     and exercise.name = cards.name
     and exercise.is_active
     and exercise.is_approved
     and (
       (exercise.image_url is not distinct from cards.old_image_url
          and exercise.motion_url is not distinct from cards.old_motion_url)
       or
       (exercise.image_url = cards.new_image_url
          and exercise.motion_url is not distinct from cards.new_motion_url)
     );
  get diagnostics matched_count = row_count;
  if matched_count <> 71 then
    raise exception 'Expected 71 unchanged or already updated exercise cards; matched %', matched_count;
  end if;
end
